input.command:
cd "C:/visual projects/reverse-kit/pipeline" && grep -n "json_nested" -A120 extractors.py | head -260; cd "C:/visual projects/sns-ref/data"; python -c "
import json
for f in ['dialog.json','map/map_summary.json','map/fortress.classic.json','loot_classic.json']:
    d=json.load(open(f,encoding='utf-8'))
    def sh(x,dep=0,k=''):
        p='  '*dep
        if isinstance(x,dict):
            print(p+k+' {dict %d}'%len(x))
            if dep<3:
                for kk,v in list(x.items())[:14]: sh(v,dep+1,str(kk))
        elif isinstance(x,list):
            print(p+k+' [list %d]'%len(x))
            if x and dep<4: sh(x[0],dep+1,'0')
        else: print(p+k+' = '+repr(x)[:40])
    print('=====',f); sh(d)
"

